import { chromium } from 'playwright';

const BASE = 'http://localhost:6006';
const STORY_ID = 'commerce-zimminlinemessage--max-quantity-reached';

const browser = await chromium.launch();
const page = await browser.newPage();
await page.goto(`${BASE}/iframe.html?id=${STORY_ID}&viewMode=story`, { waitUntil: 'networkidle' });
await page.waitForSelector('[data-testid="zimm-inline-message"]');

const info = await page.evaluate(() => {
  const el = document.querySelector('[data-testid="zimm-inline-message"]');
  const chain = [];
  let node = el;
  let depth = 0;
  while (node && depth < 8) {
    const cs = window.getComputedStyle(node);
