const { chromium } = require('playwright');

const BASE = 'http://localhost:6006';

const STORIES = [
  'commerce-zimminlinemessage--default', // "This item is unavailable" (error)
  'commerce-zimminlinemessage--partially-out-of-stock', // "Quantity unavailable in this size" (error)
  'commerce-zimminlinemessage--max-quantity-reached', // "Maximum purchase quantity reached for this size" (warning) — longest
];

const WIDTHS = [338, 226];

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 900, height: 700 } });

  const results = [];

  for (const storyId of STORIES) {
    await page.goto(`${BASE}/iframe.html?id=${storyId}&viewMode=story`, { waitUntil: 'load', timeout: 60000 });
    await page.waitForSelector('[data-testid="zimm-inline-message"]', { timeout: 60000 });

    for (const width of WIDTHS) {
      const data = await page.evaluate((w) => {
        const root = document.getElementById('storybook-root');
        // Force the exact real-world constraining container width, per the task's own
        // "wrapping div width" approach — independent of Storybook's own body padding value.
        root.style.width = w + 'px';
        root.style.maxWidth = w + 'px';
        root.style.boxSizing = 'border-box';

        const el = document.querySelector('[data-testid="zimm-inline-message"]');
        const rect = el.getBoundingClientRect();
        const cs = window.getComputedStyle(el);
        const rootRect = root.getBoundingClientRect();

        return {
          text: el.textContent,
          containerWidthPx: w,
          rootRectWidth: rootRect.width,
          elRectWidth: rect.width,
          elRectHeight: rect.height,
          scrollWidth: el.scrollWidth,
          clientWidth: el.clientWidth,
          scrollHeight: el.scrollHeight,
          clientHeight: el.clientHeight,
          horizontalOverflow: el.scrollWidth > el.clientWidth,
          verticalOverflowVsClient: el.scrollHeight > el.clientHeight,
          whiteSpace: cs.whiteSpace,
          overflowWrap: cs.overflowWrap,
          wordBreak: cs.wordBreak,
          overflowX: cs.overflowX,
          textOverflow: cs.textOverflow,
          fontSize: cs.fontSize,
          lineHeight: cs.lineHeight,
          fontWeight: cs.fontWeight,
          color: cs.color,
          documentScrollWidth: document.documentElement.scrollWidth,
          documentClientWidth: document.documentElement.clientWidth,
          pageHorizontalOverflow: document.documentElement.scrollWidth > document.documentElement.clientWidth,
        };
      }, width);

      results.push({ storyId, width, ...data });
    }
  }

  console.log(JSON.stringify(results, null, 2));
  await browser.close();
})();

